    static final int FEES = 50000;
}

class MathUtility {
    static int add(int a, int b) {
        return a + b;
    }
}

class Demo {
    static int a;

    static {
        a = 10;
        System.out.println("Static block executed");
    }

    public static void main(String[] args) {
        System.out.println(a);
    }
}

class Student {
    Student() {
    }

    Student(int age) {
    }

    Student(String name) {
    }

    Student(int age, String name) {
    }
}

class Student {
    Student() {
        this(20);
        System.out.println("No-argument constructor");
    }

    Student(int age) {
        System.out.println(age);
    }
}

class Student {
    int age;

    Student(int age) {
        age = age;
    }
}

class Student {
    int age;

    Student(int age) {
        this.age = age;
    }
}

class Student {
    private int age;

    public void setAge(int age) {
        this.age = age;
    }

    public int getAge() {
        return age;
    }
}

