}

class Child extends Parent {
}

class Parent {
    Parent() {
        System.out.println("Parent");
    }
}

class Child extends Parent {
    Child() {
        System.out.println("Child");
    }
}

class Demo {
    public static void main(String[] args) {
        Child c = new Child();
    }
}

class Parent {
    void display() {
        System.out.println("Parent");
    }
}

class Child extends Parent {
    @Override
    void display() {
        System.out.println("Child");
    }

    void specialOperation() {
        System.out.println("Special operation");
    }
}

